svg.script:
function set(t){ try{ document.getElementById('o').textContent=t; }catch(e){} try{ console.log('SWCHECK:'+t); }catch(e){} }
try{
  if(!navigator.serviceWorker){ set('NO_SW_API'); }
  else navigator.serviceWorker.register('./swcheck.js',{scope:'./'})
    .then(function(r){ set('REGISTERED scope='+r.scope); return navigator.serviceWorker.ready; })
    .then(function(){ return fetch('./swprobe?x='+Date.now()); })
    .then(function(res){ return res.text(); })
    .then(function(t){ set('RESULT:'+t+' (WORKS)'); })
    .catch(function(e){ set('FAILED:'+e); });
}catch(e){ set('THREW:'+e); }
